#!/usr/bin/env python3
"""compile_core: build core/digest.md and the per-harness adapter files from core/src/*.md. Deterministic, size-capped.

usage: compile_core.py [--check] [--root PATH]
  (default)  write core/digest.md and core/adapters/{AGENTS,GEMINI}.md
  --check    exit 1 if any generated file is not exactly what the sources compile to (for CI / doctor)
The digest is what every harness loads (Claude Code via ~/.claude/CLAUDE.md, Codex, OpenCode and Gemini/Antigravity
all read the adapter files through symlinks; they are the digest plus a short harness note), so it must stay small.
"""
import argparse
import sys
from pathlib import Path

CAP_CHARS = 24000  # ~6k tokens; the always-loaded layer must not grow unbounded
HEADER = "<!-- GENERATED by tools/compile/compile_core.py from core/src/*.md. Do not edit; edit the sources. -->\n\n"

NOTE_COMMON = """## Harness note (generated)

- **Recall.** If a `gbrain` MCP server is available, use `recall`, `context_pack` and `entity`. If not, read files:
  start at `~/second-brain/notes/INDEX.md` and `~/second-brain/notes/timeline.md`, then grep `~/second-brain/notes`
  and `~/second-brain-archive/conversations` (case-insensitive; Turkish İ/ı).
- **Write.** `brain add ...` (format: `~/second-brain/inbox/README.md`). Edit curated notes as normal files in
  `~/second-brain` and commit. Never edit generated files (`core/digest.md`, `core/adapters/*`, `skills/INDEX.md`).
"""

ADAPTERS = {
    "AGENTS.md": NOTE_COMMON,   # Claude Code (~/.claude/CLAUDE.md), Codex, OpenCode (~/.config/opencode/AGENTS.md), any reader
    "GEMINI.md": NOTE_COMMON,   # Gemini CLI / Antigravity (~/.gemini/GEMINI.md)
}


def build(root: Path) -> str:
    src = sorted((root / "core" / "src").glob("*.md"))
    if not src:
        sys.exit("no sources in core/src")
    body = "\n\n".join(p.read_text(encoding="utf-8").strip() for p in src)
    return HEADER + body + "\n"


def outputs(root: Path) -> dict:
    digest = build(root)
    out = {root / "core" / "digest.md": digest}
    for name, note in ADAPTERS.items():
        out[root / "core" / "adapters" / name] = digest + "\n" + note
    return out


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--check", action="store_true")
    ap.add_argument("--root", default=str(Path(__file__).resolve().parents[2]))
    a = ap.parse_args()
    root = Path(a.root)
    files = outputs(root)
    for path, text in files.items():
        if len(text) > CAP_CHARS:
            sys.exit(f"{path.name} is {len(text)} chars, cap is {CAP_CHARS}: trim the sources")
    digest_len = len(files[root / "core" / "digest.md"])
    if a.check:
        stale = [str(p.relative_to(root)) for p, t in files.items()
                 if not p.exists() or p.read_text(encoding="utf-8") != t]
        if stale:
            sys.exit("stale: " + ", ".join(stale) + " — run tools/compile/compile_core.py")
        print(f"ok: digest and adapters up to date ({digest_len} chars, ~{digest_len // 4} tokens, cap {CAP_CHARS})")
        return
    for path, text in files.items():
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(text, encoding="utf-8")
        print(f"wrote {path.relative_to(root)} ({len(text)} chars)")
    print(f"digest: ~{digest_len // 4} tokens, cap {CAP_CHARS} chars")


if __name__ == "__main__":
    main()
